-- ----------------------------
-- Table structure for jimu_dict_item
-- ----------------------------
DROP TABLE IF EXISTS "public"."jimu_dict_item";
CREATE TABLE "public"."jimu_dict_item" (
  "id" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "dict_id" varchar(32) COLLATE "pg_catalog"."default",
  "item_text" varchar(100) COLLATE "pg_catalog"."default",
  "item_value" varchar(100) COLLATE "pg_catalog"."default",
  "description" varchar(255) COLLATE "pg_catalog"."default",
  "sort_order" int4,
  "status" int4,
  "create_by" varchar(32) COLLATE "pg_catalog"."default",
  "create_time" timestamp(6),
  "update_by" varchar(32) COLLATE "pg_catalog"."default",
  "update_time" timestamp(6)
)
;
COMMENT ON COLUMN "public"."jimu_dict_item"."dict_id" IS '字典id';
COMMENT ON COLUMN "public"."jimu_dict_item"."item_text" IS '字典项文本';
COMMENT ON COLUMN "public"."jimu_dict_item"."item_value" IS '字典项值';
COMMENT ON COLUMN "public"."jimu_dict_item"."description" IS '描述';
COMMENT ON COLUMN "public"."jimu_dict_item"."sort_order" IS '排序';
COMMENT ON COLUMN "public"."jimu_dict_item"."status" IS '状态（1启用 0不启用）';

