-- ----------------------------
-- Table structure for jimu_report
-- ----------------------------
DROP TABLE IF EXISTS "public"."jimu_report";
CREATE TABLE "public"."jimu_report" (
  "id" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "code" varchar(50) COLLATE "pg_catalog"."default",
  "name" varchar(50) COLLATE "pg_catalog"."default",
  "note" varchar(255) COLLATE "pg_catalog"."default",
  "status" varchar(10) COLLATE "pg_catalog"."default",
  "type" varchar(10) COLLATE "pg_catalog"."default",
  "json_str" text COLLATE "pg_catalog"."default",
  "api_url" varchar(255) COLLATE "pg_catalog"."default",
  "thumb" text COLLATE "pg_catalog"."default",
  "create_by" varchar(50) COLLATE "pg_catalog"."default",
  "create_time" timestamp(6),
  "update_by" varchar(50) COLLATE "pg_catalog"."default",
  "update_time" timestamp(6),
  "del_flag" int2,
  "api_method" varchar(255) COLLATE "pg_catalog"."default",
  "api_code" varchar(255) COLLATE "pg_catalog"."default",
  "template" int2,
  "view_count" int8 DEFAULT 0,
  "css_str" text COLLATE "pg_catalog"."default",
  "js_str" text COLLATE "pg_catalog"."default",
  "tenant_id" varchar(10) COLLATE "pg_catalog"."default"
)
;
COMMENT ON COLUMN "public"."jimu_report"."id" IS '主键';
COMMENT ON COLUMN "public"."jimu_report"."code" IS '编码';
COMMENT ON COLUMN "public"."jimu_report"."name" IS '名称';
COMMENT ON COLUMN "public"."jimu_report"."note" IS '说明';
COMMENT ON COLUMN "public"."jimu_report"."status" IS '状态';
COMMENT ON COLUMN "public"."jimu_report"."type" IS '类型';
COMMENT ON COLUMN "public"."jimu_report"."json_str" IS 'json字符串';
COMMENT ON COLUMN "public"."jimu_report"."api_url" IS '请求地址';
COMMENT ON COLUMN "public"."jimu_report"."thumb" IS '缩略图';
COMMENT ON COLUMN "public"."jimu_report"."create_by" IS '创建人';
COMMENT ON COLUMN "public"."jimu_report"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."jimu_report"."update_by" IS '修改人';
COMMENT ON COLUMN "public"."jimu_report"."update_time" IS '修改时间';
COMMENT ON COLUMN "public"."jimu_report"."del_flag" IS '删除标识0-正常,1-已删除';
COMMENT ON COLUMN "public"."jimu_report"."api_method" IS '请求方法0-get,1-post';
COMMENT ON COLUMN "public"."jimu_report"."api_code" IS '请求编码';
COMMENT ON COLUMN "public"."jimu_report"."template" IS '是否是模板 0-是,1-不是';
COMMENT ON COLUMN "public"."jimu_report"."view_count" IS '浏览次数';
COMMENT ON COLUMN "public"."jimu_report"."css_str" IS 'css增强';
COMMENT ON COLUMN "public"."jimu_report"."js_str" IS 'js增强';
COMMENT ON COLUMN "public"."jimu_report"."tenant_id" IS '多租户标识';
COMMENT ON TABLE "public"."jimu_report" IS '在线excel设计器';

-- ----------------------------
