-- ----------------------------
-- Table structure for jimu_report_data_source
-- ----------------------------
DROP TABLE IF EXISTS "public"."jimu_report_data_source";
CREATE TABLE "public"."jimu_report_data_source" (
  "id" varchar(36) COLLATE "pg_catalog"."default" NOT NULL,
  "name" varchar(100) COLLATE "pg_catalog"."default",
  "report_id" varchar(100) COLLATE "pg_catalog"."default",
  "code" varchar(100) COLLATE "pg_catalog"."default",
  "remark" varchar(200) COLLATE "pg_catalog"."default",
  "db_type" varchar(10) COLLATE "pg_catalog"."default",
  "db_driver" varchar(100) COLLATE "pg_catalog"."default",
  "db_url" varchar(500) COLLATE "pg_catalog"."default",
  "db_username" varchar(100) COLLATE "pg_catalog"."default",
  "db_password" varchar(100) COLLATE "pg_catalog"."default",
  "create_by" varchar(50) COLLATE "pg_catalog"."default",
  "create_time" timestamp(6),
  "update_by" varchar(50) COLLATE "pg_catalog"."default",
  "update_time" timestamp(6),
  "connect_times" int8 DEFAULT 0,
  "tenant_id" varchar(10) COLLATE "pg_catalog"."default",
  "type" varchar(10) COLLATE "pg_catalog"."default"
)
;
COMMENT ON COLUMN "public"."jimu_report_data_source"."name" IS '数据源名称';
COMMENT ON COLUMN "public"."jimu_report_data_source"."report_id" IS '报表_id';
COMMENT ON COLUMN "public"."jimu_report_data_source"."code" IS '编码';
COMMENT ON COLUMN "public"."jimu_report_data_source"."remark" IS '备注';
COMMENT ON COLUMN "public"."jimu_report_data_source"."db_type" IS '数据库类型';
COMMENT ON COLUMN "public"."jimu_report_data_source"."db_driver" IS '驱动类';
COMMENT ON COLUMN "public"."jimu_report_data_source"."db_url" IS '数据源地址';
COMMENT ON COLUMN "public"."jimu_report_data_source"."db_username" IS '用户名';
COMMENT ON COLUMN "public"."jimu_report_data_source"."db_password" IS '密码';
COMMENT ON COLUMN "public"."jimu_report_data_source"."create_by" IS '创建人';
COMMENT ON COLUMN "public"."jimu_report_data_source"."create_time" IS '创建日期';
COMMENT ON COLUMN "public"."jimu_report_data_source"."update_by" IS '更新人';
COMMENT ON COLUMN "public"."jimu_report_data_source"."update_time" IS '更新日期';
COMMENT ON COLUMN "public"."jimu_report_data_source"."connect_times" IS '连接失败次数';
COMMENT ON COLUMN "public"."jimu_report_data_source"."tenant_id" IS '多租户标识';
COMMENT ON COLUMN "public"."jimu_report_data_source"."type" IS '类型(report:报表;drag:仪表盘)';

