-- ----------------------------
-- Table structure for jimu_report_db
-- ----------------------------
DROP TABLE IF EXISTS "public"."jimu_report_db";
CREATE TABLE "public"."jimu_report_db" (
  "id" varchar(36) COLLATE "pg_catalog"."default" NOT NULL,
  "jimu_report_id" varchar(32) COLLATE "pg_catalog"."default",
  "create_by" varchar(50) COLLATE "pg_catalog"."default",
  "update_by" varchar(50) COLLATE "pg_catalog"."default",
  "create_time" timestamp(6),
  "update_time" timestamp(6),
  "db_code" varchar(32) COLLATE "pg_catalog"."default",
  "db_ch_name" varchar(50) COLLATE "pg_catalog"."default",
  "db_type" varchar(32) COLLATE "pg_catalog"."default",
  "db_table_name" varchar(32) COLLATE "pg_catalog"."default",
  "db_dyn_sql" text COLLATE "pg_catalog"."default",
  "db_key" varchar(32) COLLATE "pg_catalog"."default",
  "tb_db_key" varchar(32) COLLATE "pg_catalog"."default",
  "tb_db_table_name" varchar(32) COLLATE "pg_catalog"."default",
  "java_type" varchar(32) COLLATE "pg_catalog"."default",
  "java_value" varchar(255) COLLATE "pg_catalog"."default",
  "api_url" varchar(255) COLLATE "pg_catalog"."default",
  "api_method" varchar(255) COLLATE "pg_catalog"."default",
  "is_list" varchar(10) COLLATE "pg_catalog"."default" DEFAULT '0'::character varying,
  "is_page" varchar(10) COLLATE "pg_catalog"."default",
  "db_source" varchar(255) COLLATE "pg_catalog"."default",
  "db_source_type" varchar(50) COLLATE "pg_catalog"."default",
  "json_data" text COLLATE "pg_catalog"."default",
  "api_convert" varchar(255) COLLATE "pg_catalog"."default"
)
;
COMMENT ON COLUMN "public"."jimu_report_db"."id" IS 'id';
COMMENT ON COLUMN "public"."jimu_report_db"."jimu_report_id" IS '主键字段';
COMMENT ON COLUMN "public"."jimu_report_db"."create_by" IS '创建人登录名称';
COMMENT ON COLUMN "public"."jimu_report_db"."update_by" IS '更新人登录名称';
COMMENT ON COLUMN "public"."jimu_report_db"."create_time" IS '创建日期';
COMMENT ON COLUMN "public"."jimu_report_db"."update_time" IS '更新日期';
COMMENT ON COLUMN "public"."jimu_report_db"."db_code" IS '数据集编码';
COMMENT ON COLUMN "public"."jimu_report_db"."db_ch_name" IS '数据集名字';
COMMENT ON COLUMN "public"."jimu_report_db"."db_type" IS '数据源类型';
COMMENT ON COLUMN "public"."jimu_report_db"."db_table_name" IS '数据库表名';
COMMENT ON COLUMN "public"."jimu_report_db"."db_dyn_sql" IS '动态查询SQL';
COMMENT ON COLUMN "public"."jimu_report_db"."db_key" IS '数据源KEY';
COMMENT ON COLUMN "public"."jimu_report_db"."tb_db_key" IS '填报数据源';
COMMENT ON COLUMN "public"."jimu_report_db"."tb_db_table_name" IS '填报数据表';
COMMENT ON COLUMN "public"."jimu_report_db"."java_type" IS 'java类数据集  类型（spring:springkey,class:java类名）';
COMMENT ON COLUMN "public"."jimu_report_db"."java_value" IS 'java类数据源  数值（bean key/java类名）';
COMMENT ON COLUMN "public"."jimu_report_db"."api_url" IS '请求地址';
COMMENT ON COLUMN "public"."jimu_report_db"."api_method" IS '请求方法0-get,1-post';
COMMENT ON COLUMN "public"."jimu_report_db"."is_list" IS '是否是列表0否1是 默认0';
COMMENT ON COLUMN "public"."jimu_report_db"."is_page" IS '是否作为分页,0:不分页，1:分页';
COMMENT ON COLUMN "public"."jimu_report_db"."db_source" IS '数据源';
COMMENT ON COLUMN "public"."jimu_report_db"."db_source_type" IS '数据库类型 MYSQL ORACLE SQLSERVER';
COMMENT ON COLUMN "public"."jimu_report_db"."json_data" IS 'json数据，直接解析json内容';
COMMENT ON COLUMN "public"."jimu_report_db"."api_convert" IS 'api转换器';

