-- ----------------------------
-- Table structure for jimu_report_db_field
-- ----------------------------
DROP TABLE IF EXISTS "public"."jimu_report_db_field";
CREATE TABLE "public"."jimu_report_db_field" (
  "id" varchar(36) COLLATE "pg_catalog"."default" NOT NULL,
  "create_by" varchar(50) COLLATE "pg_catalog"."default",
  "create_time" timestamp(6),
  "update_by" varchar(50) COLLATE "pg_catalog"."default",
  "update_time" timestamp(6),
  "jimu_report_db_id" varchar(32) COLLATE "pg_catalog"."default",
  "field_name" varchar(80) COLLATE "pg_catalog"."default",
  "field_text" varchar(50) COLLATE "pg_catalog"."default",
  "widget_type" varchar(50) COLLATE "pg_catalog"."default",
  "widget_width" int4,
  "order_num" int4,
  "search_flag" int4 DEFAULT 0,
  "search_mode" int4,
  "dict_code" varchar(255) COLLATE "pg_catalog"."default",
  "search_value" varchar(100) COLLATE "pg_catalog"."default",
  "search_format" varchar(50) COLLATE "pg_catalog"."default",
  "ext_json" text COLLATE "pg_catalog"."default"
)
;
COMMENT ON COLUMN "public"."jimu_report_db_field"."id" IS 'id';
COMMENT ON COLUMN "public"."jimu_report_db_field"."create_by" IS '创建人登录名称';
COMMENT ON COLUMN "public"."jimu_report_db_field"."create_time" IS '创建日期';
COMMENT ON COLUMN "public"."jimu_report_db_field"."update_by" IS '更新人登录名称';
COMMENT ON COLUMN "public"."jimu_report_db_field"."update_time" IS '更新日期';
COMMENT ON COLUMN "public"."jimu_report_db_field"."jimu_report_db_id" IS '数据源ID';
COMMENT ON COLUMN "public"."jimu_report_db_field"."field_name" IS '字段名';
COMMENT ON COLUMN "public"."jimu_report_db_field"."field_text" IS '字段文本';
COMMENT ON COLUMN "public"."jimu_report_db_field"."widget_type" IS '控件类型';
COMMENT ON COLUMN "public"."jimu_report_db_field"."widget_width" IS '控件宽度';
