-- ----------------------------
-- Table structure for jimu_report_db_param
-- ----------------------------
DROP TABLE IF EXISTS "public"."jimu_report_db_param";
CREATE TABLE "public"."jimu_report_db_param" (
  "id" varchar(36) COLLATE "pg_catalog"."default" NOT NULL,
  "jimu_report_head_id" varchar(36) COLLATE "pg_catalog"."default" NOT NULL,
  "param_name" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "param_txt" varchar(32) COLLATE "pg_catalog"."default",
  "param_value" varchar(1000) COLLATE "pg_catalog"."default",
  "order_num" int4,
  "create_by" varchar(50) COLLATE "pg_catalog"."default",
  "create_time" timestamp(6),
  "update_by" varchar(50) COLLATE "pg_catalog"."default",
  "update_time" timestamp(6),
  "search_flag" int4,
  "widget_type" varchar(50) COLLATE "pg_catalog"."default",
  "search_mode" int4,
  "dict_code" varchar(255) COLLATE "pg_catalog"."default",
  "search_format" varchar(50) COLLATE "pg_catalog"."default",
  "ext_json" text COLLATE "pg_catalog"."default"
)
;
COMMENT ON COLUMN "public"."jimu_report_db_param"."jimu_report_head_id" IS '动态报表ID';
COMMENT ON COLUMN "public"."jimu_report_db_param"."param_name" IS '参数字段';
COMMENT ON COLUMN "public"."jimu_report_db_param"."param_txt" IS '参数文本';
COMMENT ON COLUMN "public"."jimu_report_db_param"."param_value" IS '参数默认值';
COMMENT ON COLUMN "public"."jimu_report_db_param"."order_num" IS '排序';
COMMENT ON COLUMN "public"."jimu_report_db_param"."create_by" IS '创建人登录名称';
COMMENT ON COLUMN "public"."jimu_report_db_param"."create_time" IS '创建日期';
COMMENT ON COLUMN "public"."jimu_report_db_param"."update_by" IS '更新人登录名称';
COMMENT ON COLUMN "public"."jimu_report_db_param"."update_time" IS '更新日期';
COMMENT ON COLUMN "public"."jimu_report_db_param"."search_flag" IS '查询标识0否1是 默认0';
COMMENT ON COLUMN "public"."jimu_report_db_param"."widget_type" IS '查询控件类型';
COMMENT ON COLUMN "public"."jimu_report_db_param"."search_mode" IS '查询模式1简单2范围';
COMMENT ON COLUMN "public"."jimu_report_db_param"."dict_code" IS '字典';
COMMENT ON COLUMN "public"."jimu_report_db_param"."search_format" IS '查询时间格式化表达式';
COMMENT ON COLUMN "public"."jimu_report_db_param"."ext_json" IS '参数配置';

