-- ----------------------------
-- Table structure for jimu_report_link
-- ----------------------------
DROP TABLE IF EXISTS "public"."jimu_report_link";
CREATE TABLE "public"."jimu_report_link" (
  "id" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "report_id" varchar(32) COLLATE "pg_catalog"."default",
  "parameter" text COLLATE "pg_catalog"."default",
  "eject_type" varchar(1) COLLATE "pg_catalog"."default",
  "link_name" varchar(255) COLLATE "pg_catalog"."default",
  "api_method" varchar(1) COLLATE "pg_catalog"."default",
  "link_type" varchar(1) COLLATE "pg_catalog"."default",
  "api_url" varchar(1000) COLLATE "pg_catalog"."default",
  "link_chart_id" varchar(50) COLLATE "pg_catalog"."default",
  "expression" varchar(255) COLLATE "pg_catalog"."default",
  "requirement" varchar(255) COLLATE "pg_catalog"."default"
)
;
COMMENT ON COLUMN "public"."jimu_report_link"."id" IS '主键id';
COMMENT ON COLUMN "public"."jimu_report_link"."report_id" IS '积木设计器id';
COMMENT ON COLUMN "public"."jimu_report_link"."parameter" IS '参数';
COMMENT ON COLUMN "public"."jimu_report_link"."eject_type" IS '弹出方式（0 当前页面 1 新窗口）';
COMMENT ON COLUMN "public"."jimu_report_link"."link_name" IS '链接名称';
COMMENT ON COLUMN "public"."jimu_report_link"."api_method" IS '请求方法0-get,1-post';
COMMENT ON COLUMN "public"."jimu_report_link"."link_type" IS '链接方式(0 网络报表 1 网络连接 2 图表联动)';
COMMENT ON COLUMN "public"."jimu_report_link"."api_url" IS '外网api';
COMMENT ON COLUMN "public"."jimu_report_link"."link_chart_id" IS '联动图表的ID';
COMMENT ON COLUMN "public"."jimu_report_link"."expression" IS '表达式';
COMMENT ON COLUMN "public"."jimu_report_link"."requirement" IS '条件';
COMMENT ON TABLE "public"."jimu_report_link" IS '超链接配置表';

