-- ----------------------------
-- Table structure for jimu_report_map
-- ----------------------------
DROP TABLE IF EXISTS "public"."jimu_report_map";
CREATE TABLE "public"."jimu_report_map" (
  "id" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "label" varchar(125) COLLATE "pg_catalog"."default",
  "name" varchar(125) COLLATE "pg_catalog"."default",
  "data" text COLLATE "pg_catalog"."default",
  "create_by" varchar(32) COLLATE "pg_catalog"."default",
  "create_time" timestamp(6),
  "update_by" varchar(32) COLLATE "pg_catalog"."default",
  "update_time" timestamp(6),
  "del_flag" varchar(1) COLLATE "pg_catalog"."default",
  "sys_org_code" varchar(64) COLLATE "pg_catalog"."default"
)
;
COMMENT ON COLUMN "public"."jimu_report_map"."id" IS '主键';
COMMENT ON COLUMN "public"."jimu_report_map"."label" IS '地图名称';
COMMENT ON COLUMN "public"."jimu_report_map"."name" IS '地图编码';
COMMENT ON COLUMN "public"."jimu_report_map"."data" IS '地图数据';
COMMENT ON COLUMN "public"."jimu_report_map"."create_by" IS '创建人';
COMMENT ON COLUMN "public"."jimu_report_map"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."jimu_report_map"."update_by" IS '修改人';
COMMENT ON COLUMN "public"."jimu_report_map"."update_time" IS '修改时间';
COMMENT ON COLUMN "public"."jimu_report_map"."del_flag" IS '0表示未删除,1表示删除';
COMMENT ON COLUMN "public"."jimu_report_map"."sys_org_code" IS '所属部门';
COMMENT ON TABLE "public"."jimu_report_map" IS '地图配置表';

