-- Table structure for jimu_report_share
-- ----------------------------
DROP TABLE IF EXISTS "public"."jimu_report_share";
CREATE TABLE "public"."jimu_report_share" (
  "id" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "report_id" varchar(32) COLLATE "pg_catalog"."default",
  "preview_url" varchar(1000) COLLATE "pg_catalog"."default",
  "preview_lock" varchar(4) COLLATE "pg_catalog"."default",
  "last_update_time" timestamp(6),
  "term_of_validity" varchar(1) COLLATE "pg_catalog"."default",
  "status" varchar(1) COLLATE "pg_catalog"."default"
)
;
COMMENT ON COLUMN "public"."jimu_report_share"."id" IS '主键';
COMMENT ON COLUMN "public"."jimu_report_share"."report_id" IS '在线excel设计器id';
COMMENT ON COLUMN "public"."jimu_report_share"."preview_url" IS '预览地址';
COMMENT ON COLUMN "public"."jimu_report_share"."preview_lock" IS '密码锁';
COMMENT ON COLUMN "public"."jimu_report_share"."last_update_time" IS '最后更新时间';
COMMENT ON COLUMN "public"."jimu_report_share"."term_of_validity" IS '有效期(0:永久有效，1:1天，2:7天)';
COMMENT ON COLUMN "public"."jimu_report_share"."status" IS '是否过期(0未过期，1已过期)';
COMMENT ON TABLE "public"."jimu_report_share" IS '积木报表预览权限表';

