-- Table structure for sys_app
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_app";
CREATE TABLE "public"."sys_app" (
  "app_id" int8 NOT NULL,
  "app_name" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "app_code" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "app_icon" int8,
  "status_flag" int2 NOT NULL DEFAULT 1,
  "app_sort" numeric(10,2),
  "remark" varchar(255) COLLATE "pg_catalog"."default",
  "expand_field" text COLLATE "pg_catalog"."default",
  "version_flag" int8,
  "del_flag" char(1) COLLATE "pg_catalog"."default" NOT NULL,
  "create_time" timestamp(6),
  "create_user" int8,
  "update_time" timestamp(6),
  "update_user" int8
)
;
COMMENT ON COLUMN "public"."sys_app"."app_id" IS '主键id';
COMMENT ON COLUMN "public"."sys_app"."app_name" IS '应用名称';
COMMENT ON COLUMN "public"."sys_app"."app_code" IS '编码';
COMMENT ON COLUMN "public"."sys_app"."app_icon" IS '应用图标，存fileId，上传的图片';
COMMENT ON COLUMN "public"."sys_app"."status_flag" IS '状态：1-启用，2-禁用';
COMMENT ON COLUMN "public"."sys_app"."app_sort" IS '排序';
COMMENT ON COLUMN "public"."sys_app"."remark" IS '备注';
COMMENT ON COLUMN "public"."sys_app"."expand_field" IS '拓展字段';
COMMENT ON COLUMN "public"."sys_app"."version_flag" IS '乐观锁';
COMMENT ON COLUMN "public"."sys_app"."del_flag" IS '删除标记：Y-已删除，N-未删除';
COMMENT ON COLUMN "public"."sys_app"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_app"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_app"."update_time" IS '更新时间';
COMMENT ON COLUMN "public"."sys_app"."update_user" IS '更新人';
COMMENT ON TABLE "public"."sys_app" IS '系统应用';

