-- ----------------------------
-- Table structure for sys_database_info
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_database_info";
CREATE TABLE "public"."sys_database_info" (
  "db_id" int8 NOT NULL,
  "db_name" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "jdbc_driver" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "jdbc_url" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "username" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "password" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "schema_name" varchar(255) COLLATE "pg_catalog"."default",
  "status_flag" int2,
  "error_description" varchar(500) COLLATE "pg_catalog"."default",
  "remarks" varchar(255) COLLATE "pg_catalog"."default",
  "del_flag" char(1) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'N'::bpchar,
  "create_time" timestamp(6),
  "create_user" int8,
  "update_time" timestamp(6),
  "update_user" int8
)
;
COMMENT ON COLUMN "public"."sys_database_info"."db_id" IS '主键';
COMMENT ON COLUMN "public"."sys_database_info"."db_name" IS '数据库名称（英文名称）';
COMMENT ON COLUMN "public"."sys_database_info"."jdbc_driver" IS 'jdbc的驱动类型';
COMMENT ON COLUMN "public"."sys_database_info"."jdbc_url" IS 'jdbc的url';
COMMENT ON COLUMN "public"."sys_database_info"."username" IS '数据库连接的账号';
COMMENT ON COLUMN "public"."sys_database_info"."password" IS '数据库连接密码';
COMMENT ON COLUMN "public"."sys_database_info"."schema_name" IS '数据库的schema名称，每种数据库的schema意义都不同';
COMMENT ON COLUMN "public"."sys_database_info"."status_flag" IS '数据源状态：1-正常，2-无法连接';
COMMENT ON COLUMN "public"."sys_database_info"."error_description" IS '连接失败原因';
COMMENT ON COLUMN "public"."sys_database_info"."remarks" IS '备注，摘要';
COMMENT ON COLUMN "public"."sys_database_info"."del_flag" IS '是否删除，Y-被删除，N-未删除';
COMMENT ON COLUMN "public"."sys_database_info"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_database_info"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_database_info"."update_time" IS '修改时间';
COMMENT ON COLUMN "public"."sys_database_info"."update_user" IS '修改人';
COMMENT ON TABLE "public"."sys_database_info" IS '多数据源信息';

