-- ----------------------------
-- Table structure for sys_dict
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_dict";
CREATE TABLE "public"."sys_dict" (
  "dict_id" int8 NOT NULL,
  "dict_type_id" int8 NOT NULL,
  "dict_code" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "dict_name" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "dict_name_pinyin" varchar(255) COLLATE "pg_catalog"."default",
  "dict_encode" varchar(255) COLLATE "pg_catalog"."default",
  "dict_short_name" varchar(255) COLLATE "pg_catalog"."default",
  "dict_short_code" varchar(255) COLLATE "pg_catalog"."default",
  "dict_parent_id" int8 NOT NULL,
  "dict_pids" varchar(1000) COLLATE "pg_catalog"."default" NOT NULL,
  "status_flag" int2 NOT NULL,
  "dict_sort" numeric(10,2),
  "version_flag" int8,
  "del_flag" char(1) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'N'::bpchar,
  "create_time" timestamp(6),
  "create_user" int8,
  "update_time" timestamp(6),
  "update_user" int8
)
;
COMMENT ON COLUMN "public"."sys_dict"."dict_id" IS '字典id';
COMMENT ON COLUMN "public"."sys_dict"."dict_type_id" IS '字典类型的id';
COMMENT ON COLUMN "public"."sys_dict"."dict_code" IS '字典编码';
COMMENT ON COLUMN "public"."sys_dict"."dict_name" IS '字典名称';
COMMENT ON COLUMN "public"."sys_dict"."dict_name_pinyin" IS '字典名称首字母';
COMMENT ON COLUMN "public"."sys_dict"."dict_encode" IS '字典编码';
COMMENT ON COLUMN "public"."sys_dict"."dict_short_name" IS '字典简称';
COMMENT ON COLUMN "public"."sys_dict"."dict_short_code" IS '字典简称的编码';
COMMENT ON COLUMN "public"."sys_dict"."dict_parent_id" IS '上级字典的id(如果没有上级字典id，则为-1)';
COMMENT ON COLUMN "public"."sys_dict"."dict_pids" IS '父id集合';
COMMENT ON COLUMN "public"."sys_dict"."status_flag" IS '状态：(1-启用,2-禁用),参考 StatusEnum';
COMMENT ON COLUMN "public"."sys_dict"."dict_sort" IS '排序，带小数点';
COMMENT ON COLUMN "public"."sys_dict"."version_flag" IS '乐观锁';
COMMENT ON COLUMN "public"."sys_dict"."del_flag" IS '删除标记：Y-已删除，N-未删除';
COMMENT ON COLUMN "public"."sys_dict"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_dict"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_dict"."update_time" IS '更新时间';
COMMENT ON COLUMN "public"."sys_dict"."update_user" IS '更新人';
COMMENT ON TABLE "public"."sys_dict" IS '字典';

