DROP TABLE IF EXISTS "public"."sys_dict_type";
CREATE TABLE "public"."sys_dict_type" (
  "dict_type_id" int8 NOT NULL,
  "dict_type_class" int4,
  "dict_type_bus_code" varchar(255) COLLATE "pg_catalog"."default",
  "dict_type_code" varchar(255) COLLATE "pg_catalog"."default",
  "dict_type_name" varchar(255) COLLATE "pg_catalog"."default",
  "dict_type_name_pinyin" varchar(255) COLLATE "pg_catalog"."default",
  "dict_type_desc" varchar(255) COLLATE "pg_catalog"."default",
  "status_flag" int2,
  "dict_type_sort" numeric(10,2),
  "version_flag" int8,
  "del_flag" char(1) COLLATE "pg_catalog"."default" NOT NULL,
  "create_time" timestamp(6),
  "create_user" int8,
  "update_time" timestamp(6),
  "update_user" int8
)
;
COMMENT ON COLUMN "public"."sys_dict_type"."dict_type_id" IS '字典类型id';
COMMENT ON COLUMN "public"."sys_dict_type"."dict_type_class" IS '字典类型： 1-业务类型，2-系统类型，参考 DictTypeClassEnum';
