COMMENT ON COLUMN "public"."sys_dict_type"."dict_type_name" IS '字典类型名称';
COMMENT ON COLUMN "public"."sys_dict_type"."dict_type_name_pinyin" IS '字典类型名称首字母拼音';
COMMENT ON COLUMN "public"."sys_dict_type"."dict_type_desc" IS '字典类型描述';
COMMENT ON COLUMN "public"."sys_dict_type"."status_flag" IS '字典类型的状态：1-启用，2-禁用，参考 StatusEnum';
COMMENT ON COLUMN "public"."sys_dict_type"."dict_type_sort" IS '排序，带小数点';
COMMENT ON COLUMN "public"."sys_dict_type"."version_flag" IS '乐观锁';
COMMENT ON COLUMN "public"."sys_dict_type"."del_flag" IS '删除标记：Y-已删除，N-未删除';
COMMENT ON COLUMN "public"."sys_dict_type"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_dict_type"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_dict_type"."update_time" IS '更新时间';
COMMENT ON COLUMN "public"."sys_dict_type"."update_user" IS '更新人';
COMMENT ON TABLE "public"."sys_dict_type" IS '字典类型';

