-- ----------------------------
-- Table structure for sys_file_business
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_file_business";
CREATE TABLE "public"."sys_file_business" (
  "file_business_id" int8 NOT NULL,
  "business_code" varchar(255) COLLATE "pg_catalog"."default",
  "business_id" int8,
  "file_id" int8,
  "download_count" int4 DEFAULT 0,
  "create_time" timestamp(6),
  "create_user" int8,
  "update_time" timestamp(6),
  "update_user" int8
)
;
COMMENT ON COLUMN "public"."sys_file_business"."file_business_id" IS '主键id';
COMMENT ON COLUMN "public"."sys_file_business"."business_code" IS '业务的编码，业务自定义';
COMMENT ON COLUMN "public"."sys_file_business"."business_id" IS '业务主键id';
COMMENT ON COLUMN "public"."sys_file_business"."file_id" IS '关联文件表的id';
COMMENT ON COLUMN "public"."sys_file_business"."download_count" IS '下载次数';
COMMENT ON COLUMN "public"."sys_file_business"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_file_business"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_file_business"."update_time" IS '修改时间';
COMMENT ON COLUMN "public"."sys_file_business"."update_user" IS '修改人';
COMMENT ON TABLE "public"."sys_file_business" IS '业务关联的文件';

-- ----------------------------
-- Records of sys_file_business
-- ----------------------------

-- ----------------------------
-- Table structure for sys_file_info
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_file_info";
CREATE TABLE "public"."sys_file_info" (
  "file_id" int8 NOT NULL,
  "file_code" int8 NOT NULL,
  "file_version" int4 NOT NULL DEFAULT 1,
  "file_status" char(1) COLLATE "pg_catalog"."default" NOT NULL DEFAULT '1'::bpchar,
  "file_location" int2 NOT NULL,
  "file_bucket" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "file_origin_name" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "file_suffix" varchar(255) COLLATE "pg_catalog"."default",
  "file_size_kb" int8,
  "file_size_info" varchar(255) COLLATE "pg_catalog"."default",
  "file_object_name" varchar(255) COLLATE "pg_catalog"."default",
  "file_path" varchar(255) COLLATE "pg_catalog"."default",
  "secret_flag" char(1) COLLATE "pg_catalog"."default",
  "del_flag" char(1) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'N'::bpchar,
  "create_time" timestamp(6),
  "create_user" int8,
  "update_time" timestamp(6),
  "update_user" int8
)
;
COMMENT ON COLUMN "public"."sys_file_info"."file_id" IS '文件主键id';
COMMENT ON COLUMN "public"."sys_file_info"."file_code" IS '文件编码，本号升级的依据，解决一个文件多个版本问题，多次上传文件编码不变';
COMMENT ON COLUMN "public"."sys_file_info"."file_version" IS '文件版本，从1开始';
COMMENT ON COLUMN "public"."sys_file_info"."file_status" IS '当前状态：0-历史版,1-最新版';
COMMENT ON COLUMN "public"."sys_file_info"."file_location" IS '文件存储位置：1-阿里云，2-腾讯云，3-minio，4-本地';
COMMENT ON COLUMN "public"."sys_file_info"."file_bucket" IS '文件仓库（文件夹）';
COMMENT ON COLUMN "public"."sys_file_info"."file_origin_name" IS '文件名称（上传时候的文件全名）';
COMMENT ON COLUMN "public"."sys_file_info"."file_suffix" IS '文件后缀，例如.txt';
COMMENT ON COLUMN "public"."sys_file_info"."file_size_kb" IS '文件大小kb为单位';
COMMENT ON COLUMN "public"."sys_file_info"."file_size_info" IS '文件大小信息，计算后的';
COMMENT ON COLUMN "public"."sys_file_info"."file_object_name" IS '存储到bucket中的名称，主键id+.后缀';
COMMENT ON COLUMN "public"."sys_file_info"."file_path" IS '存储路径';
COMMENT ON COLUMN "public"."sys_file_info"."secret_flag" IS '是否为机密文件，Y-是机密，N-不是机密';
COMMENT ON COLUMN "public"."sys_file_info"."del_flag" IS '是否删除：Y-被删除，N-未删除';
COMMENT ON COLUMN "public"."sys_file_info"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_file_info"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_file_info"."update_time" IS '修改时间';
COMMENT ON COLUMN "public"."sys_file_info"."update_user" IS '修改人';
COMMENT ON TABLE "public"."sys_file_info" IS '文件信息';

