DROP TABLE IF EXISTS "public"."sys_group";
CREATE TABLE "public"."sys_group" (
  "group_id" int8 NOT NULL,
  "group_biz_code" varchar(255) COLLATE "pg_catalog"."default",
  "group_name" varchar(255) COLLATE "pg_catalog"."default",
  "business_id" int8,
  "user_id" int8,
  "create_time" timestamp(6),
  "create_user" int8,
  "update_time" timestamp(6),
  "update_user" int8
)
;
COMMENT ON COLUMN "public"."sys_group"."group_id" IS '分组id';
COMMENT ON COLUMN "public"."sys_group"."group_biz_code" IS '所属业务类别，例如：PROJECT';
COMMENT ON COLUMN "public"."sys_group"."group_name" IS '分组名称';
COMMENT ON COLUMN "public"."sys_group"."business_id" IS '业务主键id';
COMMENT ON COLUMN "public"."sys_group"."user_id" IS '所属用户id';
COMMENT ON COLUMN "public"."sys_group"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_group"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_group"."update_time" IS '更新时间';
COMMENT ON COLUMN "public"."sys_group"."update_user" IS '更新人';
COMMENT ON TABLE "public"."sys_group" IS '业务分组';

