-- ----------------------------
-- Table structure for sys_hr_organization
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_hr_organization";
CREATE TABLE "public"."sys_hr_organization" (
  "org_id" int8 NOT NULL,
  "org_parent_id" int8 NOT NULL,
  "org_pids" varchar(500) COLLATE "pg_catalog"."default" NOT NULL,
  "org_name" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "org_short_name" varchar(100) COLLATE "pg_catalog"."default",
  "org_code" varchar(50) COLLATE "pg_catalog"."default" NOT NULL,
  "org_sort" numeric(10,2) NOT NULL,
  "status_flag" int2 NOT NULL DEFAULT 1,
  "org_type" int2 DEFAULT 1,
  "tax_no" varchar(30) COLLATE "pg_catalog"."default",
  "remark" varchar(255) COLLATE "pg_catalog"."default",
  "org_level" int4,
  "master_org_id" varchar(100) COLLATE "pg_catalog"."default",
  "master_org_parent_id" varchar(100) COLLATE "pg_catalog"."default",
  "expand_field" text COLLATE "pg_catalog"."default",
  "version_flag" int8,
  "del_flag" char(1) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'N'::bpchar,
  "create_time" timestamp(6),
  "create_user" int8,
  "update_time" timestamp(6),
  "update_user" int8,
  "tenant_id" int8,
  "is_secondary_org" int4
)
;
COMMENT ON COLUMN "public"."sys_hr_organization"."org_id" IS '主键';
COMMENT ON COLUMN "public"."sys_hr_organization"."org_parent_id" IS '父id，一级节点父id是-1';
COMMENT ON COLUMN "public"."sys_hr_organization"."org_pids" IS '父ids';
COMMENT ON COLUMN "public"."sys_hr_organization"."org_name" IS '组织名称';
COMMENT ON COLUMN "public"."sys_hr_organization"."org_short_name" IS '组织机构简称';
COMMENT ON COLUMN "public"."sys_hr_organization"."org_code" IS '组织编码';
COMMENT ON COLUMN "public"."sys_hr_organization"."org_sort" IS '排序';
COMMENT ON COLUMN "public"."sys_hr_organization"."status_flag" IS '状态：1-启用，2-禁用';
COMMENT ON COLUMN "public"."sys_hr_organization"."org_type" IS '组织机构类型：1-公司，2-部门';
COMMENT ON COLUMN "public"."sys_hr_organization"."tax_no" IS '税号';
COMMENT ON COLUMN "public"."sys_hr_organization"."remark" IS '描述';
COMMENT ON COLUMN "public"."sys_hr_organization"."org_level" IS '组织机构层级';
COMMENT ON COLUMN "public"."sys_hr_organization"."master_org_id" IS '对接外部主数据的机构id';
COMMENT ON COLUMN "public"."sys_hr_organization"."master_org_parent_id" IS '对接外部主数据的父级机构id';
COMMENT ON COLUMN "public"."sys_hr_organization"."expand_field" IS '拓展字段';
COMMENT ON COLUMN "public"."sys_hr_organization"."version_flag" IS '乐观锁';
COMMENT ON COLUMN "public"."sys_hr_organization"."del_flag" IS '删除标记：Y-已删除，N-未删除';
COMMENT ON COLUMN "public"."sys_hr_organization"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_hr_organization"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_hr_organization"."update_time" IS '更新时间';
COMMENT ON COLUMN "public"."sys_hr_organization"."update_user" IS '更新人';
COMMENT ON COLUMN "public"."sys_hr_organization"."tenant_id" IS '租户号';
COMMENT ON COLUMN "public"."sys_hr_organization"."is_secondary_org" IS '是否是二级单位';
COMMENT ON TABLE "public"."sys_hr_organization" IS '组织机构信息';

