-- ----------------------------
-- Table structure for sys_log_api
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_log_api";
CREATE TABLE "public"."sys_log_api" (
  "log_id" int8 NOT NULL,
  "log_content" varchar(255) COLLATE "pg_catalog"."default",
  "app_name" varchar(255) COLLATE "pg_catalog"."default",
  "request_url" varchar(255) COLLATE "pg_catalog"."default",
  "request_params" text COLLATE "pg_catalog"."default",
  "request_result" text COLLATE "pg_catalog"."default",
  "server_ip" varchar(255) COLLATE "pg_catalog"."default",
  "client_ip" varchar(255) COLLATE "pg_catalog"."default",
  "user_id" int8,
  "user_current_org_id" int8,
  "http_method" varchar(255) COLLATE "pg_catalog"."default",
  "client_browser" varchar(255) COLLATE "pg_catalog"."default",
  "client_os" varchar(255) COLLATE "pg_catalog"."default",
  "create_time" timestamp(6),
  "create_user" int8,
  "update_time" timestamp(6),
  "update_user" int8
)
;
COMMENT ON COLUMN "public"."sys_log_api"."log_id" IS '主键';
COMMENT ON COLUMN "public"."sys_log_api"."log_content" IS '日志记录的内容';
COMMENT ON COLUMN "public"."sys_log_api"."app_name" IS '服务名称，一般为spring.application.name';
COMMENT ON COLUMN "public"."sys_log_api"."request_url" IS '当前用户请求的url';
COMMENT ON COLUMN "public"."sys_log_api"."request_params" IS 'http或方法的请求参数体';
COMMENT ON COLUMN "public"."sys_log_api"."request_result" IS 'http或方法的请求结果';
COMMENT ON COLUMN "public"."sys_log_api"."server_ip" IS '当前服务器的ip';
COMMENT ON COLUMN "public"."sys_log_api"."client_ip" IS '客户端的ip';
COMMENT ON COLUMN "public"."sys_log_api"."user_id" IS '用户id';
COMMENT ON COLUMN "public"."sys_log_api"."user_current_org_id" IS '用户请求时候的登录机构id';
COMMENT ON COLUMN "public"."sys_log_api"."http_method" IS '请求http方法';
COMMENT ON COLUMN "public"."sys_log_api"."client_browser" IS '客户浏览器标识';
COMMENT ON COLUMN "public"."sys_log_api"."client_os" IS '客户操作系统';
COMMENT ON COLUMN "public"."sys_log_api"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_log_api"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_log_api"."update_time" IS '修改时间';
COMMENT ON COLUMN "public"."sys_log_api"."update_user" IS '修改人';
COMMENT ON TABLE "public"."sys_log_api" IS 'API接口日志记录';

