-- ----------------------------
-- Table structure for sys_menu
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_menu";
CREATE TABLE "public"."sys_menu" (
  "menu_id" int8 NOT NULL,
  "menu_parent_id" int8 NOT NULL,
  "menu_pids" varchar(1000) COLLATE "pg_catalog"."default" NOT NULL,
  "menu_name" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "menu_code" varchar(50) COLLATE "pg_catalog"."default" NOT NULL,
  "app_id" int8 NOT NULL,
  "menu_sort" numeric(20,2) NOT NULL DEFAULT 100.00,
  "status_flag" int2 NOT NULL DEFAULT 1,
  "remark" varchar(255) COLLATE "pg_catalog"."default",
  "menu_type" int2,
  "antdv_router" varchar(255) COLLATE "pg_catalog"."default",
  "antdv_component" varchar(255) COLLATE "pg_catalog"."default",
  "antdv_icon" varchar(255) COLLATE "pg_catalog"."default" DEFAULT 'icon-default'::character varying,
  "antdv_link_url" varchar(255) COLLATE "pg_catalog"."default",
  "antdv_active_url" varchar(255) COLLATE "pg_catalog"."default",
  "antdv_visible" char(1) COLLATE "pg_catalog"."default" DEFAULT 'Y'::bpchar,
  "app_design_business_id" int8,
  "expand_field" text COLLATE "pg_catalog"."default",
  "version_flag" int8,
  "del_flag" char(1) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'N'::bpchar,
  "create_time" timestamp(6),
  "create_user" int8,
  "update_time" timestamp(6),
  "update_user" int8
)
;
COMMENT ON COLUMN "public"."sys_menu"."menu_id" IS '主键';
COMMENT ON COLUMN "public"."sys_menu"."menu_parent_id" IS '父id，顶级节点的父id是-1';
COMMENT ON COLUMN "public"."sys_menu"."menu_pids" IS '父id集合，中括号包住，逗号分隔';
COMMENT ON COLUMN "public"."sys_menu"."menu_name" IS '菜单的名称';
COMMENT ON COLUMN "public"."sys_menu"."menu_code" IS '菜单的编码';
COMMENT ON COLUMN "public"."sys_menu"."app_id" IS '所属应用id';
COMMENT ON COLUMN "public"."sys_menu"."menu_sort" IS '排序';
COMMENT ON COLUMN "public"."sys_menu"."status_flag" IS '状态：1-启用，2-禁用';
COMMENT ON COLUMN "public"."sys_menu"."remark" IS '备注';
COMMENT ON COLUMN "public"."sys_menu"."menu_type" IS '菜单类型：10-后台菜单，20-纯前台路由界面，30-内部链接，40-外部链接，50-应用设计';
COMMENT ON COLUMN "public"."sys_menu"."antdv_router" IS '路由地址，浏览器显示的URL，例如/menu';
COMMENT ON COLUMN "public"."sys_menu"."antdv_component" IS '前端组件名';
COMMENT ON COLUMN "public"."sys_menu"."antdv_icon" IS '图标编码';
COMMENT ON COLUMN "public"."sys_menu"."antdv_link_url" IS '外部链接地址';
COMMENT ON COLUMN "public"."sys_menu"."antdv_active_url" IS '用于非菜单显示页面的重定向url设置';
COMMENT ON COLUMN "public"."sys_menu"."antdv_visible" IS '是否可见(分离版用)：Y-是，N-否';
COMMENT ON COLUMN "public"."sys_menu"."app_design_business_id" IS '应用设计的业务id';
COMMENT ON COLUMN "public"."sys_menu"."expand_field" IS '拓展字段';
COMMENT ON COLUMN "public"."sys_menu"."version_flag" IS '乐观锁';
COMMENT ON COLUMN "public"."sys_menu"."del_flag" IS '删除标记：Y-已删除，N-未删除';
COMMENT ON COLUMN "public"."sys_menu"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_menu"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_menu"."update_time" IS '更新时间';
COMMENT ON COLUMN "public"."sys_menu"."update_user" IS '更新人';
COMMENT ON TABLE "public"."sys_menu" IS '系统菜单';

