-- ----------------------------
-- Table structure for sys_message
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_message";
CREATE TABLE "public"."sys_message" (
  "message_id" int8 NOT NULL,
  "receive_user_id" int8 NOT NULL,
  "send_user_id" int8,
  "message_title" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "message_content" text COLLATE "pg_catalog"."default",
  "message_type" varchar(255) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'NORMAL'::character varying,
  "message_url" varchar(500) COLLATE "pg_catalog"."default",
  "priority_level" varchar(50) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'low'::character varying,
  "message_send_time" timestamp(6),
  "business_id" varchar(255) COLLATE "pg_catalog"."default",
  "business_type" varchar(255) COLLATE "pg_catalog"."default",
  "read_flag" int2 DEFAULT 0,
  "version_flag" int8,
  "del_flag" char(1) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'N'::bpchar,
  "create_user" int8,
  "create_time" timestamp(6),
  "update_user" int8,
  "update_time" timestamp(6),
  "tenant_id" int8
)
;
COMMENT ON COLUMN "public"."sys_message"."message_id" IS '主键';
COMMENT ON COLUMN "public"."sys_message"."receive_user_id" IS '接收用户id';
COMMENT ON COLUMN "public"."sys_message"."send_user_id" IS '发送用户id';
COMMENT ON COLUMN "public"."sys_message"."message_title" IS '消息标题';
COMMENT ON COLUMN "public"."sys_message"."message_content" IS '消息内容';
COMMENT ON COLUMN "public"."sys_message"."message_type" IS '消息类型：NORMAL-普通类型，URL-带链接跳转';
COMMENT ON COLUMN "public"."sys_message"."message_url" IS '消息跳转的URL';
COMMENT ON COLUMN "public"."sys_message"."priority_level" IS '优先级：high-高优先级，middle-中，low-低';
COMMENT ON COLUMN "public"."sys_message"."message_send_time" IS '消息发送时间';
COMMENT ON COLUMN "public"."sys_message"."business_id" IS '关联业务id';
COMMENT ON COLUMN "public"."sys_message"."business_type" IS '业务类型(根据业务id和业务类型可以确定业务数据)';
COMMENT ON COLUMN "public"."sys_message"."read_flag" IS '阅读状态：0-未读，1-已读';
COMMENT ON COLUMN "public"."sys_message"."version_flag" IS '乐观锁';
COMMENT ON COLUMN "public"."sys_message"."del_flag" IS '是否删除：Y-被删除，N-未删除';
COMMENT ON COLUMN "public"."sys_message"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_message"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_message"."update_user" IS '修改人';
COMMENT ON COLUMN "public"."sys_message"."update_time" IS '修改时间';
COMMENT ON COLUMN "public"."sys_message"."tenant_id" IS '租户号';
COMMENT ON TABLE "public"."sys_message" IS '系统消息';

-- ----------------------------
-- Records of sys_message
-- ----------------------------

