DROP TABLE IF EXISTS "public"."sys_notice";
CREATE TABLE "public"."sys_notice" (
  "notice_id" int8 NOT NULL,
  "notice_title" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "notice_summary" varchar(255) COLLATE "pg_catalog"."default",
  "notice_content" text COLLATE "pg_catalog"."default",
  "priority_level" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "notice_begin_time" timestamp(6),
  "notice_end_time" timestamp(6),
  "notice_user_scope" text COLLATE "pg_catalog"."default",
  "publish_status" int2,
  "version_flag" int8,
  "expand_field" text COLLATE "pg_catalog"."default",
  "del_flag" char(1) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'N'::bpchar,
  "tenant_id" int8,
  "create_user" int8,
  "create_time" timestamp(6),
  "update_user" int8,
  "update_time" timestamp(6)
)
;
COMMENT ON COLUMN "public"."sys_notice"."notice_id" IS '主键';
COMMENT ON COLUMN "public"."sys_notice"."notice_title" IS '通知标题';
COMMENT ON COLUMN "public"."sys_notice"."notice_summary" IS '通知摘要';
COMMENT ON COLUMN "public"."sys_notice"."notice_content" IS '通知内容';
COMMENT ON COLUMN "public"."sys_notice"."priority_level" IS '优先级，来自字典：high-高优先级，middle-中，low-低';
COMMENT ON COLUMN "public"."sys_notice"."notice_begin_time" IS '开始时间';
COMMENT ON COLUMN "public"."sys_notice"."notice_end_time" IS '结束时间';
COMMENT ON COLUMN "public"."sys_notice"."notice_user_scope" IS '通知范围，存用户id集合';
COMMENT ON COLUMN "public"."sys_notice"."publish_status" IS '是否发布：1-已发布，2-未发布';
COMMENT ON COLUMN "public"."sys_notice"."version_flag" IS '乐观锁';
COMMENT ON COLUMN "public"."sys_notice"."expand_field" IS '拓展字段';
COMMENT ON COLUMN "public"."sys_notice"."del_flag" IS '是否删除：Y-被删除，N-未删除';
COMMENT ON COLUMN "public"."sys_notice"."tenant_id" IS '租户号';
COMMENT ON COLUMN "public"."sys_notice"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_notice"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_notice"."update_user" IS '修改人';
COMMENT ON COLUMN "public"."sys_notice"."update_time" IS '修改时间';
COMMENT ON TABLE "public"."sys_notice" IS '通知管理';

