DROP TABLE IF EXISTS "public"."sys_resource";
CREATE TABLE "public"."sys_resource" (
  "resource_id" int8 NOT NULL,
  "app_code" varchar(100) COLLATE "pg_catalog"."default",
  "resource_code" varchar(300) COLLATE "pg_catalog"."default" NOT NULL,
  "resource_name" varchar(300) COLLATE "pg_catalog"."default" NOT NULL,
  "project_code" varchar(64) COLLATE "pg_catalog"."default",
  "class_name" varchar(100) COLLATE "pg_catalog"."default",
  "method_name" varchar(100) COLLATE "pg_catalog"."default",
  "modular_code" varchar(100) COLLATE "pg_catalog"."default",
  "modular_name" varchar(100) COLLATE "pg_catalog"."default",
  "ip_address" varchar(255) COLLATE "pg_catalog"."default",
  "view_flag" char(1) COLLATE "pg_catalog"."default",
  "url" varchar(300) COLLATE "pg_catalog"."default",
  "http_method" varchar(10) COLLATE "pg_catalog"."default",
  "resource_biz_type" int2 DEFAULT 1,
