COMMENT ON COLUMN "public"."sys_resource"."project_code" IS '项目编码，一般为spring.application.name';
COMMENT ON COLUMN "public"."sys_resource"."class_name" IS '类名称';
COMMENT ON COLUMN "public"."sys_resource"."method_name" IS '方法名称';
COMMENT ON COLUMN "public"."sys_resource"."modular_code" IS '资源模块编码，一般为控制器类名排除Controller';
