-- ----------------------------
-- Table structure for sys_role
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_role";
CREATE TABLE "public"."sys_role" (
  "role_id" int8 NOT NULL,
  "role_name" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "role_code" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "role_sort" numeric(10,2) NOT NULL,
  "data_scope_type" int2 NOT NULL DEFAULT 1,
  "status_flag" int2 NOT NULL DEFAULT 1,
  "remark" varchar(255) COLLATE "pg_catalog"."default",
  "role_type" int2 NOT NULL DEFAULT 10,
  "role_company_id" int8,
  "expand_field" text COLLATE "pg_catalog"."default",
  "version_flag" int8,
  "del_flag" char(1) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'N'::bpchar,
  "create_time" timestamp(6),
  "create_user" int8,
  "update_time" timestamp(6),
  "update_user" int8,
  "tenant_id" int8
)
;
COMMENT ON COLUMN "public"."sys_role"."role_id" IS '主键id';
COMMENT ON COLUMN "public"."sys_role"."role_name" IS '角色名称';
COMMENT ON COLUMN "public"."sys_role"."role_code" IS '角色编码';
COMMENT ON COLUMN "public"."sys_role"."role_sort" IS '序号';
COMMENT ON COLUMN "public"."sys_role"."data_scope_type" IS '数据范围类型：10-仅本人数据，20-本部门数据，30-本部门及以下数据，40-指定部门数据，50-全部数据';
COMMENT ON COLUMN "public"."sys_role"."status_flag" IS '状态：1-启用，2-禁用';
COMMENT ON COLUMN "public"."sys_role"."remark" IS '备注';
COMMENT ON COLUMN "public"."sys_role"."role_type" IS '角色类型：10-系统角色，15-业务角色，20-公司角色';
COMMENT ON COLUMN "public"."sys_role"."role_company_id" IS '角色所属公司id，当角色类型为20时传此值';
COMMENT ON COLUMN "public"."sys_role"."expand_field" IS '拓展字段';
COMMENT ON COLUMN "public"."sys_role"."version_flag" IS '乐观锁';
COMMENT ON COLUMN "public"."sys_role"."del_flag" IS '删除标记：Y-已删除，N-未删除';
COMMENT ON COLUMN "public"."sys_role"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_role"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_role"."update_time" IS '更新时间';
COMMENT ON COLUMN "public"."sys_role"."update_user" IS '更新人';
COMMENT ON COLUMN "public"."sys_role"."tenant_id" IS '租户号';
COMMENT ON TABLE "public"."sys_role" IS '系统角色';

