DROP TABLE IF EXISTS "public"."sys_role_menu_options";
CREATE TABLE "public"."sys_role_menu_options" (
  "role_menu_option_id" int8 NOT NULL,
  "role_id" int8 NOT NULL,
  "app_id" int8,
  "menu_id" int8,
  "menu_option_id" int8 NOT NULL,
  "create_time" timestamp(6),
  "create_user" int8,
  "update_time" timestamp(6),
  "update_user" int8
)
;
COMMENT ON COLUMN "public"."sys_role_menu_options"."role_menu_option_id" IS '主键';
COMMENT ON COLUMN "public"."sys_role_menu_options"."role_id" IS '角色id';
COMMENT ON COLUMN "public"."sys_role_menu_options"."app_id" IS '冗余字段，菜单所属的应用id';
COMMENT ON COLUMN "public"."sys_role_menu_options"."menu_id" IS '冗余字段，功能所属的菜单id';
COMMENT ON COLUMN "public"."sys_role_menu_options"."menu_option_id" IS '菜单功能id，关联sys_menu_options主键id';
COMMENT ON COLUMN "public"."sys_role_menu_options"."create_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_role_menu_options"."create_user" IS '创建人';
COMMENT ON COLUMN "public"."sys_role_menu_options"."update_time" IS '修改时间';
COMMENT ON COLUMN "public"."sys_role_menu_options"."update_user" IS '修改人';
COMMENT ON TABLE "public"."sys_role_menu_options" IS '角色和菜单下的功能关联';

